from pathlib import Path
files={}
files['src/pages/manager/StorageLocationsPage.jsx']=r'''import {Link,useParams} from 'react-router-dom';
import {Layers,ArrowRight} from 'lucide-react';
import {useManagerData,capacity} from '@/lib/managerDemoStore';
import {assignedFacility} from '@/mocks/managerData';
import {Screen,Panel,Card,CardContent,Details,Status,Table,OpenLink,Meter,NotFound} from '@/components/manager/ManagerUI';
export default function StorageLocationsPage({level}){const data=useManagerData(),{id}=useParams(),c=capacity(data);const zone=level==='zones'?data.zones.find(r=>r.id===id):null,rack=level==='racks'?data.racks.find(r=>r.id===id):null,shelf=level==='shelves'?data.shelves.find(r=>r.id===id):null;const active=zone||rack||shelf;if(level&&!active)return <Screen title="Storage location" code="P077"><NotFound/></Screen>;const parentRack=shelf?data.racks.find(r=>r.id===shelf.rackId):rack;const parentZone=zone||data.zones.find(r=>r.id===parentRack?.zoneId);const shelves=shelf?[shelf]:rack?data.shelves.filter(s=>s.rackId===rack.id):zone?data.shelves.filter(s=>data.racks.some(r=>r.id===s.rackId&&r.zoneId===zone.id)):data.shelves;const max=shelves.reduce((s,r)=>s+r.max_volume_m3,0),used=shelves.reduce((s,r)=>s+r.used_volume_m3,0);return <Screen title={active?active.code:'Managed inventory locations'} code="P077" description="Facility → Zone → Rack → Shelf. Internal locations are managed by operations staff."><div className="manager-crumbs"><Link to="/manager/storage-locations">{assignedFacility.name}</Link>{parentZone&&<><span>→</span><Link to={`/manager/storage-locations/zones/${parentZone.id}`}>{parentZone.code}</Link></>}{parentRack&&<><span>→</span><Link to={`/manager/storage-locations/racks/${parentRack.id}`}>{parentRack.code}</Link></>}{shelf&&<><span>→</span><span>{shelf.code}</span></>}</div>{!level&&<><div className="grid gap-6 lg:grid-cols-2"><Panel title="Managed capacity"><Meter label="Available operational shelf volume" used={c.used} max={c.max}/></Panel><Panel title="Customer allocation"><Meter label="Allocated customer volume" used={c.allocated} max={c.max}/></Panel></div><div className="grid gap-5 sm:grid-cols-2">{data.zones.map(z=>{const rows=data.shelves.filter(s=>data.racks.some(r=>r.id===s.rackId&&r.zoneId===z.id));return <Card key={z.id}><CardContent><Layers className="text-[#176B3A]" size={24}/><div className="mt-4 flex justify-between gap-3"><h2 className="text-xl font-bold">{z.code}</h2><Status value={z.status}/></div><p className="mt-2 text-sm text-slate-500">{z.name} · {data.racks.filter(r=>r.zoneId===z.id).length} racks</p><div className="my-6"><Meter label="Shelf volume" used={rows.reduce((n,r)=>n+r.used_volume_m3,0)} max={rows.reduce((n,r)=>n+r.max_volume_m3,0)}/></div><OpenLink to={`/manager/storage-locations/zones/${z.id}`}>Explore zone</OpenLink></CardContent></Card>;})}</div></>}{zone&&<Panel title="Racks in this zone"><Table rows={data.racks.filter(r=>r.zoneId===id)} columns={[{key:'code',label:'Rack',render:r=><OpenLink to={`/manager/storage-locations/racks/${r.id}`}>{r.code}</OpenLink>},{key:'shelves',label:'Shelves',render:r=>data.shelves.filter(s=>s.rackId===r.id).length},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel>}{(zone||rack)&&<Panel title="Shelf capacity"><div className="mb-6"><Meter label="Total shelf volume" used={used} max={max}/></div><Table rows={shelves} columns={[{key:'code',label:'Shelf',render:r=><OpenLink to={`/manager/storage-locations/shelves/${r.id}`}>{r.code}</OpenLink>},{key:'dimensions',label:'Usable dimensions',render:r=>`${r.length} × ${r.depth} × ${r.height} m`},{key:'max_volume_m3',label:'Max volume (m³)'},{key:'used_volume_m3',label:'Used volume (m³)'},{key:'remaining',label:'Remaining (m³)',render:r=>r.max_volume_m3-r.used_volume_m3},{key:'max_weight_kg',label:'Max weight (kg)'},{key:'used_weight_kg',label:'Used weight (kg)'},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel>}{shelf&&<><div className="grid gap-6 lg:grid-cols-2"><Panel title="Shelf specifications"><Details values={[["Shelf code",shelf.code],['Status',<Status value={shelf.status}/>],['Usable length',`${shelf.length} m`],['Usable depth',`${shelf.depth} m`],['Usable height',`${shelf.height} m`],['max_volume_m3',`${shelf.max_volume_m3} m³`],['used_volume_m3',`${shelf.used_volume_m3} m³`],['Remaining volume',`${shelf.max_volume_m3-shelf.used_volume_m3} m³`],['max_weight_kg',`${shelf.max_weight_kg} kg`],['used_weight_kg',`${shelf.used_weight_kg} kg`]]}/></Panel><Panel title="Capacity indicators"><div className="space-y-8"><Meter label="Shelf volume" used={shelf.used_volume_m3} max={shelf.max_volume_m3}/><Meter label="Shelf weight" used={shelf.used_weight_kg} max={shelf.max_weight_kg} unit="kg"/></div></Panel></div><Panel title="Current items"><Table rows={data.items.filter(r=>r.shelfId===id&&r.status==='IN_STORAGE')} columns={[{key:'id',label:'Item ID'},{key:'name',label:'Item'},{key:'quantity',label:'Quantity'},{key:'rentalId',label:'Managed rental'},{key:'volume_m3',label:'Total volume (m³)'},{key:'weight_kg',label:'Total weight (kg)'},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel></>}</Screen>;}
'''
files['src/pages/manager/OperationsPage.jsx']=r'''import {useState} from 'react';
import {Link,useParams} from 'react-router-dom';
import {ClipboardCheck,UserRound} from 'lucide-react';
import {Checkbox} from '@/components/ui/checkbox';
import {useManagerData,managerDemoEnabled,assignTask,updateOperation,unitCode,customerName} from '@/lib/managerDemoStore';
import {taskTypes,managerPermissions,today} from '@/mocks/managerData';
import {Screen,Panel,Filters,Field,Select,Input,Table,OpenLink,Status,Details,Button,Textarea,Message,Timeline,NotFound,useAction} from '@/components/manager/ManagerUI';
const staffName=(data,id)=>data.staff.find(s=>s.id===id)?.name||'Unassigned';
function Assignment({task,data}){const [staff,setStaff]=useState(task.staffId||''),action=useAction();return <form className="space-y-3" onSubmit={e=>{e.preventDefault();action.run(()=>assignTask(task.id,staff),'Staff assignment saved.');}}><Field label={`Assign ${task.id}`}><Select label={`Assign ${task.id}`} value={staff} onChange={setStaff} options={[["","Select qualified staff"],...data.staff.filter(s=>s.types.includes(task.type)).map(s=>[s.id,s.name])]} required disabled={['COMPLETED','CANCELLED'].includes(task.status)}/></Field><Button size="sm" disabled={!managerDemoEnabled||!managerPermissions.assignTasks||!staff||['COMPLETED','CANCELLED'].includes(task.status)}>{task.staffId?'Reassign staff':'Assign staff'}</Button><Message {...action}/></form>;}
function OperationDetail({task,data}){const rental=data.rentals.find(r=>r.id===task.rentalId),managed=task.service==='MANAGED_INVENTORY';const [notes,setNotes]=useState(task.notes||''),[status,setStatus]=useState('IN_PROGRESS'),action=useAction();const checklist=managed?['Confirm managed rental and allocated capacity','Confirm item records / requested operation','Record staff handling and customer receipt']:['Confirm exact selected Storage Unit','Inspect condition and record findings','Confirm handover / return acknowledgement'];const [checks,setChecks]=useState(checklist.map(()=>false));const closed=['COMPLETED','CANCELLED'].includes(task.status);return <Screen title={`${task.type.replaceAll('_',' ')} · ${task.id}`} code="P025 / P026 / P030 / P039" description={managed?'Staff-managed inventory operation and capacity activation.':'Private unit inspection, handover and check-in / checkout records.'} action={<OpenLink to="/manager/operations">Daily operations</OpenLink>}><div className="grid gap-6 lg:grid-cols-2"><Panel title="Operation details"><Details values={[["Task ID",task.id],['Type',task.type.replaceAll('_',' ')],['Service',task.service.replaceAll('_',' ')],['Rental',rental?.id||'—'],['Customer',customerName(data,rental?.customerId)],['Date',task.date],['Status',<Status value={task.status}/>],['Assigned staff',staffName(data,task.staffId)],...(managed?[['Allocated capacity',`${rental?.allocated_capacity_m3||0} m³`],['Operation model','Capacity activation and staff handling'],['Customer access','Managed items are handled by staff. Customer location access is unavailable.']]:[['Exact Storage Unit',<OpenLink to={`/manager/storage-units/${rental?.unitId}`}>{unitCode(data,rental?.unitId)}</OpenLink>],['Inspection / handover','Record unit condition and acknowledgements below.']]) ]}/></Panel><Panel title="Staff assignment"><Assignment key={task.staffId} task={task} data={data}/></Panel></div><Panel title={managed?'Managed capacity / handling checklist':'Unit inspection and handover checklist'} subtitle="Manager-accessible demo record. The checklist does not execute staff inventory movements, activate real access or send credentials."><form className="space-y-5" onSubmit={e=>{e.preventDefault();action.run(()=>updateOperation(task.id,{status,notes,checks}),'Operation record updated in demo.');}}><div className="grid gap-4">{checklist.map((label,i)=><label key={label} className="flex items-start gap-3 text-sm"><Checkbox aria-label={label} checked={checks[i]} disabled={closed||!managerDemoEnabled} onCheckedChange={value=>setChecks(c=>c.map((v,j)=>j===i?value===true:v))}/>{label}</label>)}</div><div className="grid gap-5 sm:grid-cols-2"><Field label="Update task status"><Select label="Update task status" value={status} onChange={setStatus} options={['IN_PROGRESS','COMPLETED']} disabled={closed}/></Field><Field label="Operational notes"><Textarea aria-label="Operational notes" required value={notes} onChange={e=>setNotes(e.target.value)} disabled={closed}/></Field></div><Message {...action}/><Button disabled={closed||!managerDemoEnabled||!managerPermissions.manageOperations}>Save operation record</Button>{closed&&<p className="text-xs text-slate-500">This task is closed.</p>}</form></Panel><Panel title="Operation timeline"><Timeline entries={task.timeline}/></Panel></Screen>;}
export default function OperationsPage({assignment=false}){const data=useManagerData(),{id}=useParams(),[date,setDate]=useState(assignment?'':today),[type,setType]=useState(''),[status,setStatus]=useState(''),[staff,setStaff]=useState('');if(id){const task=data.tasks.find(t=>t.id===id);return task?<OperationDetail key={id} task={task} data={data}/>:<Screen title="Operation"><NotFound/></Screen>;}
const rows=data.tasks.filter(r=>(!date||r.date===date)&&(!type||r.type===type)&&(!status||r.status===status)&&(!staff||(staff==='UNASSIGNED'?!r.staffId:r.staffId===staff)));return <Screen title={assignment?'Staff assignment':'Daily operations'} code={assignment?'P044':'P045'} description={assignment?'Assign qualified staff from this facility and balance their open workload.':'Coordinate check-ins, inspections, handovers, support, maintenance and managed inventory tasks.'}>{assignment&&<><div className="grid gap-4 md:grid-cols-3">{data.staff.map(s=><Panel key={s.id} title={s.name} subtitle={s.role}><p className="text-3xl font-bold">{data.tasks.filter(t=>t.staffId===s.id&&!['COMPLETED','CANCELLED'].includes(t.status)).length}</p><p className="mt-2 text-xs text-slate-500">Open tasks · {data.tasks.filter(t=>t.staffId===s.id&&t.status==='COMPLETED').length} completed</p></Panel>)}</div><Panel title="Unassigned tasks" subtitle={`${data.tasks.filter(t=>!t.staffId&&!['COMPLETED','CANCELLED'].includes(t.status)).length} tasks need a qualified staff member`}><Table rows={data.tasks.filter(t=>!t.staffId&&!['COMPLETED','CANCELLED'].includes(t.status))} columns={[{key:'id',label:'Task',render:r=><OpenLink to={`/manager/operations/${r.id}`}>{r.id}</OpenLink>},{key:'type',label:'Type',render:r=>r.type.replaceAll('_',' ')},{key:'date',label:'Date'},{key:'status',label:'Status',render:r=><Status value={r.status}/>},{key:'assign',label:'Assignment',render:r=><Assignment key={r.staffId||'new'} task={r} data={data}/>} ]}/></Panel></>}
<Panel title={assignment?'All facility tasks':'Operations board'}><Filters><Field label="Date"><Input type="date" aria-label="Operation date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="Task type"><Select label="Operation type" value={type} onChange={setType} options={[["","All task types"],...taskTypes]}/></Field><Field label="Status"><Select label="Operation status" value={status} onChange={setStatus} options={[["","All statuses"],'PENDING','IN_PROGRESS','COMPLETED','CANCELLED']}/></Field><Field label="Staff"><Select label="Operation staff" value={staff} onChange={setStaff} options={[["","All staff"],['UNASSIGNED','Unassigned'],...data.staff.map(s=>[s.id,s.name])]}/></Field></Filters>{assignment?<Table rows={rows} columns={[{key:'id',label:'Task',render:r=><OpenLink to={`/manager/operations/${r.id}`}>{r.id}</OpenLink>},{key:'type',label:'Type',render:r=>r.type.replaceAll('_',' ')},{key:'date',label:'Date'},{key:'status',label:'Status',render:r=><Status value={r.status}/>},{key:'staffId',label:'Staff',render:r=>staffName(data,r.staffId)},{key:'assign',label:'Reassign',render:r=><Assignment key={r.staffId||'new'} task={r} data={data}/>} ]}/>:<div className="manager-board">{['PENDING','IN_PROGRESS','COMPLETED'].map(column=><div className="manager-board-column" key={column}><div className="flex justify-between"><Status value={column}/><span className="text-xs">{rows.filter(r=>r.status===column).length}</span></div>{rows.filter(r=>r.status===column).map(task=><article className="manager-task-card" key={task.id}><div className="flex items-center gap-2 text-xs font-bold text-[#176B3A]"><ClipboardCheck size={16}/>{task.type.replaceAll('_',' ')}</div><h3 className="mt-3 text-sm font-bold">{task.resource}</h3><p className="mt-2 text-[11px] text-slate-500">{task.id} · {task.date}<br/>{task.service.replaceAll('_',' ')}</p><p className="my-3 flex items-center gap-2 text-xs"><UserRound size={14}/>{staffName(data,task.staffId)}</p><OpenLink to={`/manager/operations/${task.id}`}>Open operation</OpenLink></article>)}{!rows.some(r=>r.status===column)&&<p className="py-8 text-center text-xs text-slate-500">No matching tasks.</p>}</div>)}</div>}</Panel></Screen>;}
'''
files['src/pages/manager/ExtensionsPage.jsx']=r'''import {useState} from 'react';
import {useManagerData,extensionQuote,decide,unitCode,customerName,money} from '@/lib/managerDemoStore';
import {managerPermissions} from '@/mocks/managerData';
import {Screen,Panel,Details,Status,Filters,Select,Field,Decision,Timeline} from '@/components/manager/ManagerUI';
export default function ExtensionsPage(){const data=useManagerData(),[status,setStatus]=useState('PENDING');const rows=data.extensions.filter(r=>!status||r.status===status);return <Screen title="Extension approvals" code="P029" description="Review rental time extensions and managed capacity upgrades before approval."><Panel title="Review queue"><Filters><Field label="Status"><Select label="Extension status" value={status} onChange={setStatus} options={[["","All statuses"],'PENDING','APPROVED','REJECTED']}/></Field></Filters><p className="text-xs text-slate-500">Demo pricing: managed capacity upgrade is 200,000 VND / m³ / month. Time extensions use the rental’s monthly price.</p></Panel>{rows.map(request=>{const rental=data.rentals.find(r=>r.id===request.rentalId),quote=extensionQuote(data,request);return <Panel key={request.id} title={request.id} subtitle={`${rental?.service.replaceAll('_',' ')} · ${request.kind==='CAPACITY'?'Capacity upgrade':'Time extension'}`}><div className="grid gap-6 lg:grid-cols-2"><Details values={[["Existing rental",rental?.id],['Customer',customerName(data,rental?.customerId)],['Unit / allocated capacity',rental?.service==='SELF_STORAGE'?unitCode(data,rental.unitId):`${rental?.allocated_capacity_m3} m³`],['Current rental end',rental?.end],['Requested change',request.kind==='CAPACITY'?`Upgrade to ${request.requested_capacity_m3} m³ for ${request.months} month(s)`:`Add ${request.months} month(s)`],['Projected change',request.status==='APPROVED'?'Applied to the demo rental':quote.label],['Availability result',request.status==='PENDING'?(quote.available?'Available':'Unavailable / conflicting allocation'):'Reviewed'],['Calculated charge',money(request.calculatedCharge??quote.charge)],['Charge calculation',quote.formula],['Status',<Status value={request.status}/>]]}/><div className="space-y-6"><Decision status={request.status} available={quote.available} allowed={managerPermissions.approveExtensions} onDecision={(decision,reason)=>decide('extensions',request.id,decision,reason)}/><Timeline entries={request.timeline}/></div></div></Panel>;})}{!rows.length&&<Panel title="No matching extension requests"/>}</Screen>;}
'''
for name,content in files.items():
 p=Path(name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
